    if (ssm_success) {
        print("✅ Matrix Memory SSM test passed\n", .{});
    } else {
        print("❌ Matrix Memory SSM test failed\n", .{});
    }

    // Test 2: Per-token sparsity verification
    print("🧪 Test 2: Per-token conditional sparsity...\n", .{});
    const test_tokens = [_]u32{1, 2, 3, 4};
