    const sparsity_success = SSMCore.compute_per_token_sparsity(
        &test_tokens[0], &sparsity_masks[0], test_tokens.len, 512
    );
    if (sparsity_success) {
        print("✅ Per-token sparsity test passed\n", .{});
    } else {
        print("❌ Per-token sparsity test failed\n", .{});
    }

    // Test 3: Neuroszimbolikus reasoning verification
    print("🧪 Test 3: Neuroszimbolikus reasoning engine...\n", .{});
    const reasoning_success = NeuroSymbolic.test_logical_reasoning("Test query");
    if (reasoning_success) {
        print("✅ Neuroszimbolikus reasoning test passed\n", .{});
    } else {
        print("❌ Neuroszimbolikus reasoning test failed\n", .{});
    }

    // Test 4: Full system integration
    print("🧪 Test 4: Full V21 system integration...\n", .{});
    const config = JAIDEV21Config{};
    var system = try JAIDEV21System.init(allocator, config);
    defer system.deinit();

    _ = try system.runNeuroszimbolikusInference("Test system verification with neuroszimbolikus reasoning");
    print("✅ Full system integration test passed\n", .{});

    print("\n🎉 All JAIDE V21 system verification tests completed!\n", .{});
}

// Main entry point
pub fn main() !void {
    print("================================================================================\n", .{});
    print("   JAIDE V21 - Neuroszimbolikus SSM System\n", .{});
    print("   Matrix Memory + Per-token Sparsity + Neuroszimbolikus Reasoning\n", .{});
    print("================================================================================\n", .{});

    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
