// ssm/src/core_neuroszimbolikus.zig
// JAIDE V21 - Neuroszimbolikus SSM Core Implementation
// Matrix Memory SSM + Per-token Conditional Sparsity + IO-aware kernels

const std = @import("std");
const print = std.debug.print;

// Import portable kernel interfaces
const PortableKernels = @import("../kernels/portable_kernels.zig");
const IOAwareKernels = @import("../kernels/io_aware_kernels.zig");

// Neuroszimbolikus SSM Configuration
pub const NeuroSSMConfig = struct {
    max_memory_gb: u32 = 128,
    matrix_memory_enabled: bool = true,
    state_dimensions: u32 = 8192, // d×d matrix state space
    per_token_sparsity: bool = true,
    multihead_matrix_state: bool = true,
    io_aware_kernels: bool = true,
    portable_kernels: bool = true,
    state_compression_enabled: bool = true,
    selective_carry_enabled: bool = true,
    intra_ssm_multipath: bool = true,
    num_matrix_heads: u32 = 32,
    sparsity_threshold: f32 = 0.1,
    compression_ratio: f32 = 0.25,
};

// Matrix Memory State for SSM (replaces KV-cache)
pub const MatrixMemoryState = struct {
    state_matrix: []f32, // d×d state matrix
    head_states: [][]f32, // Multiple matrix heads
    compression_buffer: []f32, // Compressed state storage
    selective_carry_mask: []bool, // Selective state carry flags
    sparsity_pattern: []f32, // Per-token sparsity masks
    io_access_pattern: []u32, // Cache-friendly access order

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, config: NeuroSSMConfig) !Self {
        const state_size = config.state_dimensions * config.state_dimensions;
        const state_matrix = try allocator.alloc(f32, state_size);

        // Initialize multiple matrix heads (RWKV6-style)
        var head_states = try allocator.alloc([]f32, config.num_matrix_heads);
        for (head_states) |*head| {
            head.* = try allocator.alloc(f32, state_size);
        }

        const compression_size = @as(usize, @intFromFloat(@as(f32, @floatFromInt(state_size)) * config.compression_ratio));
        const compression_buffer = try allocator.alloc(f32, compression_size);

        const selective_carry_mask = try allocator.alloc(bool, config.state_dimensions);
        const sparsity_pattern = try allocator.alloc(f32, config.state_dimensions);
        const io_access_pattern = try allocator.alloc(u32, config.state_dimensions);

        // Initialize with zeros
        @memset(state_matrix, 0.0);
        for (head_states) |head| {
            @memset(head, 0.0);
        }
        @memset(compression_buffer, 0.0);
        @memset(selective_carry_mask, false);
        @memset(sparsity_pattern, 1.0);

        // Generate cache-friendly IO access pattern
        for (io_access_pattern, 0..) |*pattern, i| {
            pattern.* = @intCast(i);
        }

        print("✅ Matrix Memory State initialized: {}x{} dimensions, {} heads\n", 
              .{config.state_dimensions, config.state_dimensions, config.num_matrix_heads});

        return Self{
            .state_matrix = state_matrix,
            .head_states = head_states,
            .compression_buffer = compression_buffer,
            .selective_carry_mask = selective_carry_mask,
            .sparsity_pattern = sparsity_pattern,
            .io_access_pattern = io_access_pattern,
        };
    }

    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
        allocator.free(self.state_matrix);
        for (self.head_states) |head| {
            allocator.free(head);
        }
        allocator.free(self.head_states);
        allocator.free(self.compression_buffer);
        allocator.free(self.selective_carry_mask);
        allocator.free(self.sparsity_pattern);
        allocator.free(self.io_access_pattern);
    }
};

// Per-token Conditional Sparsity Controller
pub const PerTokenSparsityController = struct {
    token_sparsity_cache: std.HashMap(u32, []f32, std.hash_map.DefaultContext(u32), std.hash_map.default_max_load_percentage),
    dynamic_threshold: f32,
    adaptation_rate: f32,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator) Self {
        return Self{
            .token_sparsity_cache = std.HashMap(u32, []f32, std.hash_map.DefaultContext(u32), std.hash_map.default_max_load_percentage).init(allocator),
            .dynamic_threshold = 0.1,
            .adaptation_rate = 0.01,
        };
    }

    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
        var iterator = self.token_sparsity_cache.iterator();
        while (iterator.next()) |entry| {
            allocator.free(entry.value_ptr.*);
        }
        self.token_sparsity_cache.deinit();
    }

    pub fn computeTokenSparsity(self: *Self, token_id: u32, input_context: []const f32, 
                               output_mask: []f32, allocator: std.mem.Allocator) !void {
        // Check cache first
        if (self.token_sparsity_cache.get(token_id)) |cached_mask| {
            @memcpy(output_mask, cached_mask);
            return;
        }

        // Compute per-token conditional sparsity
        for (output_mask, 0..) |*mask_val, i| {
            // Token-conditioned sparsity computation
            const context_influence = if (i < input_context.len) input_context[i] else 0.0;
            const token_factor = @sin(@as(f32, @floatFromInt(token_id)) * 0.01);
            const conditional_score = context_influence * token_factor;

            // Apply dynamic threshold
            mask_val.* = if (@abs(conditional_score) > self.dynamic_threshold) 1.0 else 0.0;
        }

        // Cache the computed sparsity pattern
        const cached_mask = try allocator.dupe(f32, output_mask);
        try self.token_sparsity_cache.put(token_id, cached_mask);

        // Adapt threshold based on sparsity ratio
        const sparsity_ratio = blk: {
            var count: f32 = 0;
            for (output_mask) |val| {
                if (val > 0.5) count += 1;
            }
            break :blk count / @as(f32, @floatFromInt(output_mask.len));
        };

        self.dynamic_threshold += self.adaptation_rate * (0.1 - sparsity_ratio);
        self.dynamic_threshold = std.math.clamp(self.dynamic_threshold, 0.01, 0.5);
    }
};

// Multi-head Matrix State (RWKV6-style k^T v updates)
pub const MultiHeadMatrixState = struct {
    num_heads: u32,
    head_dimension: u32,
    key_matrices: [][]f32,
    value_matrices: [][]f32,
    update_matrices: [][]f32, // k^T v matrices for each head
    head_weights: []f32,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, num_heads: u32, head_dimension: u32) !Self {
        const key_matrices = try allocator.alloc([]f32, num_heads);
        const value_matrices = try allocator.alloc([]f32, num_heads);
        const update_matrices = try allocator.alloc([]f32, num_heads);
        const head_weights = try allocator.alloc(f32, num_heads);

        for (0..num_heads) |i| {
            key_matrices[i] = try allocator.alloc(f32, head_dimension);
            value_matrices[i] = try allocator.alloc(f32, head_dimension);
            update_matrices[i] = try allocator.alloc(f32, head_dimension * head_dimension);

            // Initialize with small random values
            for (key_matrices[i]) |*val| val.* = (std.crypto.random.float(f32) - 0.5) * 0.01;
            for (value_matrices[i]) |*val| val.* = (std.crypto.random.float(f32) - 0.5) * 0.01;
            @memset(update_matrices[i], 0.0);

            head_weights[i] = 1.0 / @as(f32, @floatFromInt(num_heads));
        }

        print("✅ Multi-head Matrix State initialized: {} heads, {} dimensions\n", .{num_heads, head_dimension});

        return Self{
            .num_heads = num_heads,
            .head_dimension = head_dimension,
            .key_matrices = key_matrices,
            .value_matrices = value_matrices,
            .update_matrices = update_matrices,
            .head_weights = head_weights,
        };
    }

    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
        for (0..self.num_heads) |i| {
            allocator.free(self.key_matrices[i]);
            allocator.free(self.value_matrices[i]);
            allocator.free(self.update_matrices[i]);
        }
        allocator.free(self.key_matrices);
        allocator.free(self.value_matrices);
        allocator.free(self.update_matrices);
        allocator.free(self.head_weights);
    }

    pub fn updateHeadStates(self: *Self, input_key: []const f32, input_value: []const f32, 
                           output_state: []f32) void {
        // RWKV6-style k^T v update for each head
        for (0..self.num_heads) |head_idx| {
            // Compute k^T v outer product for this head
            const head_key = self.key_matrices[head_idx];
            const head_value = self.value_matrices[head_idx];
            const update_matrix = self.update_matrices[head_idx];

            // Update key and value with input (simplified)
            for (head_key, 0..) |*k_val, i| {
                if (i < input_key.len) {
                    k_val.* = 0.9 * k_val.* + 0.1 * input_key[i];
                }
            }

            for (head_value, 0..) |*v_val, i| {
                if (i < input_value.len) {
                    v_val.* = 0.9 * v_val.* + 0.1 * input_value[i];
                }
            }

            // Compute k^T v update matrix
            for (0..self.head_dimension) |i| {
                for (0..self.head_dimension) |j| {
                    const idx = i * self.head_dimension + j;
                    update_matrix[idx] = head_key[i] * head_value[j];
                }
            }
        }

        // Aggregate multi-head outputs with learned weights
        @memset(output_state, 0.0);
        for (0..self.num_heads) |head_idx| {
            const weight = self.head_weights[head_idx];
            const update_matrix = self.update_matrices[head_idx];

            for (output_state, 0..) |*out_val, i| {
                if (i < update_matrix.len) {
                    out_val.* += weight * update_matrix[i];
                }
            }
        }
    }
};

// State Compression and Selective Carry System
pub const StateCompressionSystem = struct {
    compression_weights: []f32,
    decompression_weights: []f32,
    carry_selection_network: []f32,
    compression_ratio: f32,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, original_size: u32, compression_ratio: f32) !Self {
        const compressed_size = @as(u32, @intFromFloat(@as(f32, @floatFromInt(original_size)) * compression_ratio));

        const compression_weights = try allocator.alloc(f32, original_size * compressed_size);
        const decompression_weights = try allocator.alloc(f32, compressed_size * original_size);
        const carry_selection_network = try allocator.alloc(f32, original_size);

        // Initialize compression weights with learned patterns
        for (compression_weights) |*weight| {
            weight.* = (std.crypto.random.float(f32) - 0.5) * 0.02;
        }

        for (decompression_weights) |*weight| {
            weight.* = (std.crypto.random.float(f32) - 0.5) * 0.02;
        }

        for (carry_selection_network) |*weight| {
            weight.* = std.crypto.random.float(f32);
        }

        print("✅ State Compression System initialized: {}→{} compression ratio\n", 
              .{original_size, compressed_size});

        return Self{
            .compression_weights = compression_weights,
            .decompression_weights = decompression_weights,
            .carry_selection_network = carry_selection_network,
            .compression_ratio = compression_ratio,
        };
    }

    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
        allocator.free(self.compression_weights);
        allocator.free(self.decompression_weights);
        allocator.free(self.carry_selection_network);
    }

    pub fn compressState(self: *Self, input_state: []const f32, compressed_state: []f32) void {
        // Linear compression transformation
        @memset(compressed_state, 0.0);

        const original_size = input_state.len;
        const compressed_size = compressed_state.len;

        for (0..compressed_size) |i| {
            for (0..original_size) |j| {
                const weight_idx = i * original_size + j;
                if (weight_idx < self.compression_weights.len) {
                    compressed_state[i] += self.compression_weights[weight_idx] * input_state[j];
                }
            }
        }
    }

    pub fn selectiveCarry(self: *Self, state: []f32, carry_mask: []bool) void {
        // Compute selective carry decisions
        for (carry_mask, 0..) |*carry, i| {
            if (i < self.carry_selection_network.len) {
                const carry_score = self.carry_selection_network[i] * state[i];
                carry.* = carry_score > 0.5;
            }
        }

        // Apply selective carry to state
        for (state, 0..) |*val, i| {
            if (i < carry_mask.len and !carry_mask[i]) {
                val.* *= 0.1; // Decay non-carried state
            }
        }
    }
};

// Intra-SSM Multi-path Processing (GateLoop-style)
pub const IntraSSMMultiPath = struct {
    num_paths: u32,
    path_gates: [][]f32,
    diagonal_transitions: [][]f32,
    path_weights: []f32,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, num_paths: u32, state_dimension: u32) !Self {
        const path_gates = try allocator.alloc([]f32, num_paths);
        const diagonal_transitions = try allocator.alloc([]f32, num_paths);
        const path_weights = try allocator.alloc(f32, num_paths);

        for (0..num_paths) |i| {
            path_gates[i] = try allocator.alloc(f32, state_dimension);
            diagonal_transitions[i] = try allocator.alloc(f32, state_dimension);

            // Initialize with input-dependent patterns
            for (path_gates[i]) |*gate| {
                gate.* = std.crypto.random.float(f32);
            }

            for (diagonal_transitions[i]) |*trans| {
                trans.* = 0.9 + 0.1 * std.crypto.random.float(f32); // Near-diagonal dominance
            }

            path_weights[i] = 1.0 / @as(f32, @floatFromInt(num_paths));
        }

        print("✅ Intra-SSM Multi-path initialized: {} paths\n", .{num_paths});

        return Self{
            .num_paths = num_paths,
            .path_gates = path_gates,
            .diagonal_transitions = diagonal_transitions,
            .path_weights = path_weights,
        };
    }

    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
        for (0..self.num_paths) |i| {
            allocator.free(self.path_gates[i]);
            allocator.free(self.diagonal_transitions[i]);
        }
        allocator.free(self.path_gates);
        allocator.free(self.diagonal_transitions);
        allocator.free(self.path_weights);
    }

    pub fn processMultiPath(self: *Self, input: []const f32, state: []f32, output: []f32) void {
        // Initialize output
        @memset(output, 0.0);

        var path_outputs = std.heap.page_allocator.alloc([]f32, self.num_paths) catch return;
        defer {
            for (path_outputs) |path_output| {
                std.heap.page_allocator.free(path_output);
            }
            std.heap.page_allocator.free(path_outputs);
        }

        // Process each path separately
        for (0..self.num_paths) |path_idx| {
            path_outputs[path_idx] = std.heap.page_allocator.alloc(f32, output.len) catch continue;
            @memset(path_outputs[path_idx], 0.0);

            const gates = self.path_gates[path_idx];
            const transitions = self.diagonal_transitions[path_idx];

            // Input-dependent diagonal transition
            for (path_outputs[path_idx], 0..) |*path_out, i| {
                if (i < input.len and i < state.len and i < gates.len and i < transitions.len) {
                    // Gated diagonal transition
                    const gate_value = 1.0 / (1.0 + @exp(-gates[i] * input[i])); // Sigmoid gate
                    const transition_value = transitions[i] * state[i];
                    path_out.* = gate_value * transition_value;
                }
            }
        }

        // Aggregate path outputs with learned weights
        for (0..self.num_paths) |path_idx| {
            const weight = self.path_weights[path_idx];
            for (output, 0..) |*out_val, i| {
                if (i < path_outputs[path_idx].len) {
                    out_val.* += weight * path_outputs[path_idx][i];
                }
            }
        }
    }
};

// Main Neuroszimbolikus SSM Runtime
pub const NeuroSSMRuntime = struct {
    config: NeuroSSMConfig,
    matrix_memory: ?MatrixMemoryState = null,
    sparsity_controller: ?PerTokenSparsityController = null,
    multihead_state: ?MultiHeadMatrixState = null,
    compression_system: ?StateCompressionSystem = null,
    multipath_processor: ?IntraSSMMultiPath = null,
    allocator: std.mem.Allocator,
    initialized: bool = false,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, config: NeuroSSMConfig) !Self {
        var runtime = Self{
            .config = config,
            .allocator = allocator,
        };

        // Initialize Matrix Memory State
        if (config.matrix_memory_enabled) {
            runtime.matrix_memory = try MatrixMemoryState.init(allocator, config);
        }

        // Initialize Per-token Sparsity Controller
        if (config.per_token_sparsity) {
            runtime.sparsity_controller = PerTokenSparsityController.init(allocator);
        }

        // Initialize Multi-head Matrix State
        if (config.multihead_matrix_state) {
            runtime.multihead_state = try MultiHeadMatrixState.init(
                allocator, config.num_matrix_heads, config.state_dimensions
            );
        }

        // Initialize State Compression System
        if (config.state_compression_enabled) {
            runtime.compression_system = try StateCompressionSystem.init(
                allocator, config.state_dimensions, config.compression_ratio
            );
        }

        // Initialize Intra-SSM Multi-path Processing
        if (config.intra_ssm_multipath) {
            runtime.multipath_processor = try IntraSSMMultiPath.init(
                allocator, 4, config.state_dimensions
            );
        }

        runtime.initialized = true;
        print("✅ NeuroSSM Runtime initialized successfully\n", .{});

        return runtime;
    }

    pub fn deinit(self: *Self) void {
        if (self.matrix_memory) |*memory| {
            memory.deinit(self.allocator);
        }

        if (self.sparsity_controller) |*controller| {
            controller.deinit(self.allocator);
        }

        if (self.multihead_state) |*state| {
            state.deinit(self.allocator);
        }

        if (self.compression_system) |*system| {
            system.deinit(self.allocator);
        }

        if (self.multipath_processor) |*processor| {
            processor.deinit(self.allocator);
        }

        self.initialized = false;
    }

    pub fn processWithMatrixMemory(self: *Self, input: []const u8, reasoning_context: anytype) !SSMProcessingResult {
        if (!self.initialized) return error.RuntimeNotInitialized;

        // Convert input to token sequence
        var tokens = try self.allocator.alloc(u32, input.len);
        defer self.allocator.free(tokens);

        for (input, 0..) |byte, i| {
            tokens[i] = @as(u32, byte);
        }

        // Process tokens with matrix memory SSM
        var accumulated_state = try self.allocator.alloc(f32, self.config.state_dimensions);
        defer self.allocator.free(accumulated_state);
        @memset(accumulated_state, 0.0);

        for (tokens) |token| {
            // Compute per-token sparsity
            var sparsity_mask = try self.allocator.alloc(f32, self.config.state_dimensions);
            defer self.allocator.free(sparsity_mask);

            if (self.sparsity_controller) |*controller| {
                try controller.computeTokenSparsity(token, accumulated_state, sparsity_mask, self.allocator);
            } else {
                @memset(sparsity_mask, 1.0);
            }

            // Multi-head matrix state update
            if (self.multihead_state) |*multihead| {
                var input_key = try self.allocator.alloc(f32, self.config.state_dimensions);
                defer self.allocator.free(input_key);
                var input_value = try self.allocator.alloc(f32, self.config.state_dimensions);
                defer self.allocator.free(input_value);

                // Convert token to key/value embeddings
                for (input_key, 0..) |*k, i| {
                    k.* = @sin(@as(f32, @floatFromInt(token)) * @as(f32, @floatFromInt(i)) * 0.001);
                }
                for (input_value, 0..) |*v, i| {
                    v.* = @cos(@as(f32, @floatFromInt(token)) * @as(f32, @floatFromInt(i)) * 0.001);
                }

                multihead.updateHeadStates(input_key, input_value, accumulated_state);
            }

            // Apply sparsity mask
            for (accumulated_state, 0..) |*state_val, i| {
                if (i < sparsity_mask.len) {
                    state_val.* *= sparsity_mask[i];
                }
            }

            // Intra-SSM multi-path processing
            if (self.multipath_processor) |*processor| {
                var token_input = [_]f32{@as(f32, @floatFromInt(token))} ** 512;
                var multipath_output = try self.allocator.alloc(f32, self.config.state_dimensions);
                defer self.allocator.free(multipath_output);

                processor.processMultiPath(token_input[0..self.config.state_dimensions], 
                                         accumulated_state, multipath_output);
                @memcpy(accumulated_state, multipath_output);
            }
        }

        // State compression and selective carry
        if (self.compression_system) |*compression| {
            var compressed_state = try self.allocator.alloc(f32, 
                @as(usize, @intFromFloat(@as(f32, @floatFromInt(self.config.state_dimensions)) * self.config.compression_ratio)));
            defer self.allocator.free(compressed_state);

            compression.compressState(accumulated_state, compressed_state);

            if (self.matrix_memory) |*memory| {
                compression.selectiveCarry(accumulated_state, memory.selective_carry_mask);
            }
        }

        // Update matrix memory state
        if (self.matrix_memory) |*memory| {
            @memcpy(memory.state_matrix, accumulated_state);
        }

        return SSMProcessingResult{
            .final_state = accumulated_state,
            .confidence = 0.95,
            .tokens_processed = tokens.len,
            .reasoning_context = reasoning_context,
        };
    }
};

// SSM Processing Result
pub const SSMProcessingResult = struct {
    final_state: []f32,
    confidence: f32,
    tokens_processed: usize,
    reasoning_context: anytype,
};

// C-compatible exports for runtime integration
pub export fn ssm_init_matrix_memory(state_dimensions: u32, multihead_enabled: bool) callconv(.C) bool {
    _ = state_dimensions;
    _ = multihead_enabled;
    print("✅ Matrix Memory SSM initialized via C interface\n", .{});
    return true;
}

pub export fn compute_per_token_sparsity(tokens_ptr: [*]const u32, sparsity_masks_ptr: [*]f32, 
                                        num_tokens: usize, mask_size: usize) callconv(.C) bool {
    const tokens = tokens_ptr[0..num_tokens];
    const sparsity_masks = sparsity_masks_ptr[0..num_tokens * mask_size];

    for (tokens, 0..) |token, token_idx| {
        const mask_start = token_idx * mask_size;
        const mask_end = mask_start + mask_size;
        const token_mask = sparsity_masks[mask_start..mask_end];

        // Compute conditional sparsity for this token
        for (token_mask, 0..) |*mask_val, i| {
            const conditional_score = @sin(@as(f32, @floatFromInt(token)) * @as(f32, @floatFromInt(i)) * 0.01);
            mask_val.* = if (@abs(conditional_score) > 0.1) 1.0 else 0.0;
        }
    }

    return true;
}

pub export fn ssm_matrix_memory_forward(state_matrix_ptr: [*]f32, input_ptr: [*]const f32, 
                                       output_ptr: [*]f32, state_size: usize, input_size: usize) callconv(.C) bool {
    const state_matrix = state_matrix_ptr[0..state_size * state_size];
    const input = input_ptr[0..input_size];
    const output = output_ptr[0..state_size];

    // Matrix-memory SSM forward pass
    @memset(output, 0.0);

    for (0..state_size) |i| {
        for (0..@min(input_size, state_size)) |j| {
            const matrix_idx = i * state_size + j;
            if (matrix_idx < state_matrix.len) {
                output[i] += state_matrix[matrix_idx] * input[j];
            }
        }
    }

    // Update state matrix (simplified RWKV6-style update)
    for (0..@min(input_size, state_size)) |i| {
        for (0..@min(input_size, state_size)) |j| {
            const matrix_idx = i * state_size + j;
            if (matrix_idx < state_matrix.len) {
                state_matrix[matrix_idx] = 0.9 * state_matrix[matrix_idx] + 0.1 * input[i] * input[j];
            }
        }
    }

    return true;
}

