        const elements_per_cache_line = self.cache_line_size / @sizeOf(f32);

        // Sort access pattern by cache line alignment
        std.mem.sort(u32, access_pattern, elements_per_cache_line, struct {
            fn lessThan(elements_per_line: u32, a: u32, b: u32) bool {
                const cache_line_a = a / elements_per_line;
                const cache_line_b = b / elements_per_line;
                return cache_line_a < cache_line_b;
            }
        }.lessThan);
    }

    fn optimizeForLatency(self: *Self, data_ptr: [*]f32, size: usize, access_pattern: []u32) void {
