// neurosymbolic/src/reasoning_engine.zig
// JAIDE V21 - Neuroszimbolikus Reasoning Engine
// Szabály-alapú neurális-szimbolikus hibrid gondolkodási rendszer

const std = @import("std");
const print = std.debug.print;

// Import logical fact store and rule synthesis components
const LogicalFactStore = @import("logical_fact_store.zig").LogicalFactStore;
const RuleBasedSynthesis = @import("rule_synthesis.zig").RuleBasedSynthesis;
const SymbolicRAG = @import("symbolic_rag.zig").SymbolicRAG;

// Neuroszimbolikus Reasoning Configuration
pub const ReasoningConfig = struct {
    logical_fact_store: bool = true,
    rule_based_synthesis: bool = true,
    neuroszimbolikus_rag: bool = true,
    formal_invariants: bool = true,
    max_reasoning_depth: u32 = 10,
    min_confidence_threshold: f32 = 0.7,
    symbolic_weight: f32 = 0.6,
    neural_weight: f32 = 0.4,
    proof_search_timeout_ms: u32 = 5000,
    fact_consistency_checking: bool = true,
};

// Logical Fact Representation
pub const LogicalFact = struct {
    predicate: []const u8,
    arguments: [][]const u8,
    truth_value: f32, // Fuzzy truth value [0.0, 1.0]
    source: FactSource,
    timestamp: u64,
    confidence: f32,

    const FactSource = enum {
        NEURAL_EXTRACTION,
        SYMBOLIC_RULE,
        USER_INPUT,
        EXTERNAL_KB,
        INFERENCE,
    };
};

// Logical Rule Representation
pub const LogicalRule = struct {
    antecedent: []LogicalCondition,
    consequent: LogicalFact,
    rule_strength: f32,
    rule_type: RuleType,
    activation_count: u32,

    const RuleType = enum {
        DEDUCTIVE,
        INDUCTIVE,
        ABDUCTIVE,
        DEFEASIBLE,
    };

    const LogicalCondition = struct {
        fact_pattern: LogicalFact,
        negated: bool,
        quantifier: Quantifier,
    };

    const Quantifier = enum {
        UNIVERSAL,  // ∀
        EXISTENTIAL, // ∃
        NONE,
    };
};

// Reasoning Context
pub const ReasoningContext = struct {
    query: []const u8,
    relevant_facts: std.ArrayList(LogicalFact),
    applicable_rules: std.ArrayList(LogicalRule),
    reasoning_trace: std.ArrayList(ReasoningStep),
    confidence_score: f32,
    reasoning_type: ReasoningType,

    const ReasoningType = enum {
        FORWARD_CHAINING,
        BACKWARD_CHAINING,
        HYBRID_NEURAL_SYMBOLIC,
        PROOF_SEARCH,
    };

    const ReasoningStep = struct {
        step_type: StepType,
        input_facts: []LogicalFact,
        applied_rule: ?LogicalRule,
        output_fact: ?LogicalFact,
        confidence_change: f32,
        explanation: []const u8,
    };

    const StepType = enum {
        FACT_LOOKUP,
        RULE_APPLICATION,
        NEURAL_INFERENCE,
        CONSISTENCY_CHECK,
        PROOF_STEP,
    };
};

// Main Neuroszimbolikus Reasoning Engine
pub const ReasoningEngine = struct {
    config: ReasoningConfig,
    fact_store: ?LogicalFactStore = null,
    rule_synthesizer: ?RuleBasedSynthesis = null,
    symbolic_rag: ?SymbolicRAG = null,
    allocator: std.mem.Allocator,
    reasoning_cache: std.HashMap([]const u8, ReasoningContext, std.hash_map.StringContext, std.hash_map.default_max_load_percentage),
    active_reasoning_sessions: std.ArrayList(ReasoningSession),

    const ReasoningSession = struct {
        session_id: []const u8,
        context: ReasoningContext,
        start_time: u64,
        timeout_ms: u32,
        status: SessionStatus,
    };

    const SessionStatus = enum {
        ACTIVE,
        COMPLETED,
        TIMEOUT,
        FAILED,
    };

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator, config: ReasoningConfig) !Self {
        var engine = Self{
            .config = config,
            .allocator = allocator,
            .reasoning_cache = std.HashMap([]const u8, ReasoningContext, std.hash_map.StringContext, std.hash_map.default_max_load_percentage).init(allocator),
            .active_reasoning_sessions = std.ArrayList(ReasoningSession).init(allocator),
        };

        // Initialize Logical Fact Store
        if (config.logical_fact_store) {
            engine.fact_store = try LogicalFactStore.init(allocator);
            print("✅ Logical Fact Store initialized\n", .{});
        }

        // Initialize Rule-based Synthesis
        if (config.rule_based_synthesis) {
            engine.rule_synthesizer = try RuleBasedSynthesis.init(allocator);
            print("✅ Rule-based Synthesis Engine initialized\n", .{});
        }

        // Initialize Symbolic RAG
        if (config.neuroszimbolikus_rag) {
            engine.symbolic_rag = try SymbolicRAG.init(allocator);
            print("✅ Neuroszimbolikus RAG initialized\n", .{});
        }

        // Load foundational knowledge base
        try engine.loadFoundationalKnowledge();

        return engine;
    }

    pub fn deinit(self: *Self) void {
        if (self.fact_store) |*store| {
            store.deinit();
        }

        if (self.rule_synthesizer) |*synthesizer| {
            synthesizer.deinit();
        }

        if (self.symbolic_rag) |*rag| {
            rag.deinit();
        }

        // Clean up reasoning cache
        var cache_iterator = self.reasoning_cache.iterator();
        while (cache_iterator.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.relevant_facts.deinit();
            entry.value_ptr.applicable_rules.deinit();
            entry.value_ptr.reasoning_trace.deinit();
        }
        self.reasoning_cache.deinit();

        self.active_reasoning_sessions.deinit();
    }

    pub fn analyzePrompt(self: *Self, prompt: []const u8) !ReasoningContext {
        // Check cache first
        if (self.reasoning_cache.get(prompt)) |cached_context| {
            print("📋 Using cached reasoning context for prompt\n", .{});
            return cached_context;
        }

        // Create new reasoning context
        var context = ReasoningContext{
            .query = try self.allocator.dupe(u8, prompt),
            .relevant_facts = std.ArrayList(LogicalFact).init(self.allocator),
            .applicable_rules = std.ArrayList(LogicalRule).init(self.allocator),
            .reasoning_trace = std.ArrayList(ReasoningStep).init(self.allocator),
            .confidence_score = 0.0,
            .reasoning_type = .HYBRID_NEURAL_SYMBOLIC,
        };

        // Step 1: Symbolic RAG retrieval
        if (self.symbolic_rag) |*rag| {
            const retrieved_facts = try rag.retrieveRelevantFacts(prompt);
            try context.relevant_facts.appendSlice(retrieved_facts);
        }

        // Step 2: Extract logical structure from prompt
        try self.extractLogicalStructure(prompt, &context);

        // Step 3: Find applicable rules
        if (self.rule_synthesizer) |*synthesizer| {
            const applicable_rules = try synthesizer.findApplicableRules(context.relevant_facts.items);
            try context.applicable_rules.appendSlice(applicable_rules);
        }

        // Step 4: Compute initial confidence
        context.confidence_score = self.computeInitialConfidence(&context);

        // Cache the context
        const prompt_copy = try self.allocator.dupe(u8, prompt);
        try self.reasoning_cache.put(prompt_copy, context);

        print("🧠 Analyzed prompt: {} facts, {} rules, {:.2} confidence\n", 
              .{context.relevant_facts.items.len, context.applicable_rules.items.len, context.confidence_score});

        return context;
    }

    pub fn performLogicalReasoning(self: *Self, query: []const u8) !ReasoningResult {
        const session_id = try self.generateSessionId();
        const start_time = std.time.milliTimestamp();

        // Initialize reasoning context
        var context = try self.analyzePrompt(query);

        // Create reasoning session
        const session = ReasoningSession{
            .session_id = session_id,
            .context = context,
            .start_time = @intCast(start_time),
            .timeout_ms = self.config.proof_search_timeout_ms,
            .status = .ACTIVE,
        };
        try self.active_reasoning_sessions.append(session);

        // Perform hybrid neural-symbolic reasoning
        const reasoning_result = try self.executeHybridReasoning(&context);

        // Update session status
        for (self.active_reasoning_sessions.items) |*s| {
            if (std.mem.eql(u8, s.session_id, session_id)) {
                s.status = if (reasoning_result.success) .COMPLETED else .FAILED;
                break;
            }
        }

        return reasoning_result;
    }

