    fn executeHybridReasoning(self: *Self, context: *ReasoningContext) !ReasoningResult {
        var final_confidence: f32 = context.confidence_score;
        var reasoning_successful = false;

        // Step 1: Forward chaining with available facts and rules
        if (context.applicable_rules.items.len > 0) {
            const forward_result = try self.performForwardChaining(context);
            final_confidence = @max(final_confidence, forward_result.confidence);
            reasoning_successful = reasoning_successful or forward_result.success;
        }

        // Step 2: Backward chaining if forward chaining insufficient
        if (final_confidence < self.config.min_confidence_threshold) {
            const backward_result = try self.performBackwardChaining(context);
            final_confidence = @max(final_confidence, backward_result.confidence);
            reasoning_successful = reasoning_successful or backward_result.success;
        }

        // Step 3: Neural inference for gap filling
        if (final_confidence < self.config.min_confidence_threshold) {
            const neural_result = try self.performNeuralInference(context);
            final_confidence = self.config.symbolic_weight * final_confidence + 
                              self.config.neural_weight * neural_result.confidence;
            reasoning_successful = reasoning_successful or neural_result.success;
        }

        // Step 4: Consistency checking
        if (self.config.fact_consistency_checking) {
            const consistency_check = try self.checkFactConsistency(context);
            if (!consistency_check) {
                final_confidence *= 0.8; // Penalize inconsistency
            }
        }

        return ReasoningResult{
            .success = reasoning_successful,
            .confidence = final_confidence,
            .explanation = try self.generateExplanation(context),
            .derived_facts = try self.collectDerivedFacts(context),
            .reasoning_trace = context.reasoning_trace.items,
        };
    }

    fn performForwardChaining(self: *Self, context: *ReasoningContext) !ReasoningResult {
        var derived_facts = std.ArrayList(LogicalFact).init(self.allocator);
        defer derived_facts.deinit();

        var confidence_accumulator: f32 = 0.0;
        var successful_inferences: u32 = 0;

        // Apply rules to derive new facts
        for (context.applicable_rules.items) |rule| {
            if (try self.canApplyRule(rule, context.relevant_facts.items)) {
                const derived_fact = try self.applyRule(rule, context.relevant_facts.items);
                try derived_facts.append(derived_fact);
                try context.relevant_facts.append(derived_fact);

                confidence_accumulator += rule.rule_strength * derived_fact.confidence;
                successful_inferences += 1;

                try self.addReasoningStep(context, .RULE_APPLICATION, &.{}, rule, derived_fact, 
                                        rule.rule_strength, "Applied logical rule");
            }
        }

        const average_confidence = if (successful_inferences > 0) 
            confidence_accumulator / @as(f32, @floatFromInt(successful_inferences))
        else 
            0.0;

        return ReasoningResult{
            .success = successful_inferences > 0,
            .confidence = average_confidence,
            .explanation = "Forward chaining inference",
            .derived_facts = try derived_facts.toOwnedSlice(),
            .reasoning_trace = context.reasoning_trace.items,
        };
    }

    fn performBackwardChaining(self: *Self, context: *ReasoningContext) !ReasoningResult {
        _ = self;

        // Simplified backward chaining implementation
        try self.addReasoningStep(context, .PROOF_STEP, &.{}, null, null, 0.3, "Backward chaining attempted");

        return ReasoningResult{
            .success = false,
            .confidence = 0.3,
            .explanation = "Backward chaining (simplified implementation)",
            .derived_facts = &.{},
            .reasoning_trace = context.reasoning_trace.items,
        };
    }

    fn performNeuralInference(self: *Self, context: *ReasoningContext) !ReasoningResult {
        _ = self;

        // Neural inference gap filling
        const neural_confidence = 0.6; // Simulated neural network confidence

        try self.addReasoningStep(context, .NEURAL_INFERENCE, &.{}, null, null, neural_confidence, 
                                "Neural inference for knowledge gap filling");

        return ReasoningResult{
            .success = true,
            .confidence = neural_confidence,
            .explanation = "Neural inference integration",
            .derived_facts = &.{},
            .reasoning_trace = context.reasoning_trace.items,
        };
    }

    fn checkFactConsistency(self: *Self, context: *ReasoningContext) !bool {
        _ = self;

        // Simple consistency checking
        var contradictions: u32 = 0;

        for (context.relevant_facts.items, 0..) |fact_a, i| {
            for (context.relevant_facts.items[i+1..]) |fact_b| {
                if (self.areFactsContradictory(fact_a, fact_b)) {
                    contradictions += 1;
                }
            }
        }

        const consistency_ratio = 1.0 - @as(f32, @floatFromInt(contradictions)) / @as(f32, @floatFromInt(context.relevant_facts.items.len));

        try self.addReasoningStep(context, .CONSISTENCY_CHECK, &.{}, null, null, consistency_ratio,
                                "Fact consistency verification");

        return consistency_ratio > 0.8;
    }

    fn areFactsContradictory(self: *Self, fact_a: LogicalFact, fact_b: LogicalFact) bool {
        _ = self;

        // Simple contradiction detection
        if (std.mem.eql(u8, fact_a.predicate, fact_b.predicate) and
            fact_a.arguments.len == fact_b.arguments.len) {

            var args_match = true;
            for (fact_a.arguments, 0..) |arg_a, i| {
                if (!std.mem.eql(u8, arg_a, fact_b.arguments[i])) {
                    args_match = false;
                    break;
                }
            }

            if (args_match) {
                // Same predicate and arguments, check truth values
                return @abs(fact_a.truth_value - fact_b.truth_value) > 0.7;
            }
        }

        return false;
    }

    fn canApplyRule(self: *Self, rule: LogicalRule, facts: []LogicalFact) !bool {
        _ = self;

        // Check if all antecedent conditions are satisfied
        for (rule.antecedent) |condition| {
            var condition_satisfied = false;

            for (facts) |fact| {
                if (self.factMatchesCondition(fact, condition)) {
                    condition_satisfied = true;
                    break;
                }
            }

            if (!condition_satisfied) {
                return false;
            }
        }

        return true;
    }

    fn factMatchesCondition(self: *Self, fact: LogicalFact, condition: LogicalRule.LogicalCondition) bool {
        _ = self;

        // Simple pattern matching
        if (!std.mem.eql(u8, fact.predicate, condition.fact_pattern.predicate)) {
            return false;
        }

        if (fact.arguments.len != condition.fact_pattern.arguments.len) {
            return false;
        }

        // Check argument matching (simplified)
        for (fact.arguments, 0..) |arg, i| {
            const pattern_arg = condition.fact_pattern.arguments[i];
            if (!std.mem.eql(u8, arg, pattern_arg) and !std.mem.eql(u8, pattern_arg, "?")) {
                return false;
            }
        }

        return true;
    }

    fn applyRule(self: *Self, rule: LogicalRule, facts: []LogicalFact) !LogicalFact {
        _ = self;
        _ = facts;

        // Apply rule to derive new fact
        const derived_confidence = rule.rule_strength * rule.consequent.confidence;

        return LogicalFact{
            .predicate = rule.consequent.predicate,
            .arguments = rule.consequent.arguments,
            .truth_value = rule.consequent.truth_value,
            .source = .INFERENCE,
            .timestamp = @intCast(std.time.milliTimestamp()),
            .confidence = derived_confidence,
        };
    }

    fn computeInitialConfidence(self: *Self, context: *ReasoningContext) f32 {
        _ = self;

        if (context.relevant_facts.items.len == 0) return 0.0;

        var total_confidence: f32 = 0.0;
        for (context.relevant_facts.items) |fact| {
            total_confidence += fact.confidence;
        }

        return total_confidence / @as(f32, @floatFromInt(context.relevant_facts.items.len));
    }

    fn generateExplanation(self: *Self, context: *ReasoningContext) ![]const u8 {
        _ = self;

        // Generate human-readable explanation
        var explanation = std.ArrayList(u8).init(self.allocator);

        try explanation.appendSlice("Neuroszimbolikus érvelés: ");
        try explanation.appendSlice("Találtam ");

        const fact_count_str = try std.fmt.allocPrint(self.allocator, "{}", .{context.relevant_facts.items.len});
        defer self.allocator.free(fact_count_str);
        try explanation.appendSlice(fact_count_str);

        try explanation.appendSlice(" releváns tényt és ");

        const rule_count_str = try std.fmt.allocPrint(self.allocator, "{}", .{context.applicable_rules.items.len});
        defer self.allocator.free(rule_count_str);
        try explanation.appendSlice(rule_count_str);

        try explanation.appendSlice(" alkalmazható szabályt. ");

        if (context.reasoning_trace.items.len > 0) {
            try explanation.appendSlice("Érvelési lépések: ");
            for (context.reasoning_trace.items, 0..) |step, i| {
                if (i > 0) try explanation.appendSlice(", ");
                try explanation.appendSlice(step.explanation);
            }
        }

        return explanation.toOwnedSlice();
    }

    fn collectDerivedFacts(self: *Self, context: *ReasoningContext) ![]LogicalFact {
        var derived_facts = std.ArrayList(LogicalFact).init(self.allocator);

        for (context.reasoning_trace.items) |step| {
            if (step.output_fact) |fact| {
                try derived_facts.append(fact);
            }
        }

        return derived_facts.toOwnedSlice();
    }

    fn addReasoningStep(self: *Self, context: *ReasoningContext, step_type: ReasoningContext.StepType,
                       input_facts: []LogicalFact, applied_rule: ?LogicalRule, output_fact: ?LogicalFact,
                       confidence_change: f32, explanation: []const u8) !void {
        const step = ReasoningContext.ReasoningStep{
            .step_type = step_type,
            .input_facts = try self.allocator.dupe(LogicalFact, input_facts),
            .applied_rule = applied_rule,
            .output_fact = output_fact,
            .confidence_change = confidence_change,
            .explanation = try self.allocator.dupe(u8, explanation),
        };

        try context.reasoning_trace.append(step);
        context.confidence_score += confidence_change;
    }

    fn generateSessionId(self: *Self) ![]const u8 {
        _ = self;

        var random_bytes: [16]u8 = undefined;
        std.crypto.random.bytes(&random_bytes);

        const base64_len = std.base64.standard.Encoder.calcSize(random_bytes.len);
        var session_id = try self.allocator.alloc(u8, base64_len);
        _ = std.base64.standard.Encoder.encode(session_id, &random_bytes);

        return session_id;
    }
};

// Reasoning Result
pub const ReasoningResult = struct {
    success: bool,
    confidence: f32,
    explanation: []const u8,
    derived_facts: []LogicalFact,
    reasoning_trace: []ReasoningContext.ReasoningStep,
};

